style.css:
@-moz-document domain("chat.openai.com") {
/* Style the toggle label as a button */
  #toggleLabel {
    position: fixed;
    bottom: 10px;
    left: 10px;
    background: #333;
    color: #fff;
    padding: 8px 12px;
    border-radius: 4px;
    cursor: pointer;
    z-index: 10000;
    font-family: sans-serif;
    user-select: none;
  }
  
  /* When the checkbox is checked, hide everything except the main conversation (<main>) and the text input area (assumed to have class .text-input) and the toggle */
  #uiToggle:checked ~ *:not(main):not(.text-input):not(#toggleLabel):not(#uiToggle) {
    display: none !important;
  }
}
